-- Seed inventory sample data covering every Inventory submodule: product master
-- (categories, brands, attributes, templates, variants, prices), warehousing (storage categories,
-- warehouses, supply relations, locations, putaway rules) and stock operations (operation types,
-- transfers of all three operation codes, moves, move lines, quants with counts due, and scraps).
-- Aligns with 0005001_inventory_schema.sql. Org IDs match 0002002_iam_identity_seeds.sql; the
-- currency ID matches 0001004_essential_currency_seeds.sql. Every enum value here is taken from
-- the Go constants in nikkierp/modules/inventory/domain/models, not invented.
--
-- IAM resources and actions for the Inventory module live in 0005002_inventory_iam.sql, not here,
-- so a reviewer can see the module's entire permission surface in one file.
--
-- Units of measure (essential_uomcats / essential_uoms) are seeded in 0001003_essential_seeds.sql,
-- not here: they belong to the Essential module, not Inventory, and other modules need them too.
-- This file's "uom_id" / "base_uom_id" / "inventory_uom_id" references below point at the
-- 01K5INV...UOMCAT0n / 01K5INV...UOM000n rows seeded there -- those ids must stay in step with
-- this file's usage since Inventory has no FK onto essential_uoms.
--
-- Two organizations are populated so multi-org filtering is exercised:
--   01JWNY20G23KD4RV5VWYABQYHD  "My Company"      -- the bulk of the data
--   01K1H7M2K9VW3P5R7XQJY2C1Z9  "Tech Solutions"  -- a second, smaller footprint
--
-- ID prefixes are stable and greppable: ...UOM..., ...STOR..., ...WH...., ...LOC...., ...PUT....,
-- ...OPTYPE, ...XFER..., ...MOVE..., ...MVLN..., ...QUANT.., ...SCRAP.., ...PRICE..

DO $$
BEGIN
	IF EXISTS (
		SELECT FROM information_schema.tables
		WHERE table_schema = 'public' AND table_name = 'inventory_product_templates'
	) THEN
		-- Storage categories. Covers all three allow_new_item_policy values, with and without a
		-- max_weight cap, plus one archived row and one belonging to the second org.
		INSERT INTO "inventory_storage_categories" ("id", "code", "name", "max_weight", "allow_new_item_policy", "description", "org_id", "is_archived", "created_at", "updated_at", "etag") VALUES
		('01K5INV0000000000STOR00001', 'ambient', jsonb_build_object('en-US', 'Ambient shelving', 'vi-VN', 'Kệ thường'), 1500, 'allow', jsonb_build_object('en-US', 'Room-temperature racking, mixed products allowed', 'vi-VN', 'Kệ nhiệt độ phòng, cho phép hàng hỗn hợp'), '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV0000000000STOR00002', 'chilled', jsonb_build_object('en-US', 'Chilled cabinet', 'vi-VN', 'Tủ mát'), 400, 'same_product_only', jsonb_build_object('en-US', '2-8 degrees C, one product per bin to avoid cross-contamination', 'vi-VN', '2-8 độ C, mỗi ngăn một sản phẩm'), '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV0000000000STOR00003', 'bulk_pallet', jsonb_build_object('en-US', 'Bulk pallet floor', 'vi-VN', 'Sàn pallet'), 12000, 'empty_only', jsonb_build_object('en-US', 'Full-pallet floor slots, only assignable when empty', 'vi-VN', 'Ô sàn pallet nguyên, chỉ nhận khi trống'), '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV0000000000STOR00004', 'high_value', jsonb_build_object('en-US', 'High-value cage', 'vi-VN', 'Lồng hàng giá trị cao'), NULL, 'allow', jsonb_build_object('en-US', 'Locked cage, no weight limit configured', 'vi-VN', 'Lồng khoá, không giới hạn khối lượng'), '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV0000000000STOR00005', 'archived_cat', jsonb_build_object('en-US', 'Retired mezzanine', 'vi-VN', 'Gác lửng đã ngưng'), 300, 'allow', NULL, '01JWNY20G23KD4RV5VWYABQYHD', TRUE, NOW(), NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV0000000000STOR00006', 'ambient', jsonb_build_object('en-US', 'Ambient shelving', 'vi-VN', 'Kệ thường'), 800, 'allow', NULL, '01K1H7M2K9VW3P5R7XQJY2C1Z9', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text)
		ON CONFLICT ("id") DO NOTHING;

