		('01K5INV00000000000WH000001', 'WH-CENTRAL', jsonb_build_object('en-US', 'Central Distribution Centre', 'vi-VN', 'Trung tâm phân phối'), 'central', NULL, '12 Nguyen Van Linh, District 7, Ho Chi Minh City', '01JZQFFDKY8T4JB8R6NSY1331J', 'three_step', 'three_step', 'active', 'Receives all imports; three-step in (receive/quality/stock) and out (pick/pack/ship).', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000002', 'WH-NORTH', jsonb_build_object('en-US', 'Northern Regional Warehouse', 'vi-VN', 'Kho khu vực miền Bắc'), 'sub', '01K5INV00000000000WH000001', '45 Pham Van Dong, Bac Tu Liem, Ha Noi', '01JWNXT3EY7FG47VDJTEPTDC98', 'two_step', 'two_step', 'active', 'Replenished from the central DC.', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000003', 'WH-SOUTH', jsonb_build_object('en-US', 'Southern Regional Warehouse', 'vi-VN', 'Kho khu vực miền Nam'), 'sub', '01K5INV00000000000WH000001', '88 Vo Van Kiet, District 5, Ho Chi Minh City', '01JZQFZFK6GM2D5X6MYHWH6FND', 'one_step', 'two_step', 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000004', 'WH-POS-Q1', jsonb_build_object('en-US', 'District 1 Store Backroom', 'vi-VN', 'Kho sau cửa hàng Quận 1'), 'pos', '01K5INV00000000000WH000003', '200 Le Loi, District 1, Ho Chi Minh City', NULL, 'one_step', 'one_step', 'active', 'Point-of-sale backroom; single-step in and out.', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000005', 'WH-3PL', jsonb_build_object('en-US', 'Third-party Overflow Site', 'vi-VN', 'Kho thuê ngoài'), 'other', NULL, 'Lot C3, VSIP II, Binh Duong', NULL, 'one_step', 'one_step', 'suspended', 'Contract paused; kept for historical stock only.', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000006', 'WH-OLD', jsonb_build_object('en-US', 'Decommissioned Depot', 'vi-VN', 'Kho đã đóng'), 'other', NULL, NULL, NULL, 'one_step', 'one_step', 'suspended', 'Archived: closed in 2025.', '01JWNY20G23KD4RV5VWYABQYHD', TRUE, NOW(), NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000007', 'WH-TECH-MAIN', jsonb_build_object('en-US', 'Tech Solutions Main Store', 'vi-VN', 'Kho chính Tech Solutions'), 'central', NULL, '9 Duy Tan, Cau Giay, Ha Noi', NULL, 'two_step', 'one_step', 'active', NULL, '01K1H7M2K9VW3P5R7XQJY2C1Z9', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text)
		ON CONFLICT ("id") DO NOTHING;

