		INSERT INTO "inventory_warehouse_supply_relations" ("id", "source_warehouse_id", "destination_warehouse_id", "priority", "is_default", "org_id", "is_archived", "created_at", "updated_at", "etag") VALUES
		('01K5INV000000000WHSUPPLY01', '01K5INV00000000000WH000001', '01K5INV00000000000WH000002', 1, TRUE, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000WHSUPPLY02', '01K5INV00000000000WH000003', '01K5INV00000000000WH000002', 2, FALSE, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000WHSUPPLY03', '01K5INV00000000000WH000001', '01K5INV00000000000WH000003', 1, TRUE, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000WHSUPPLY04', '01K5INV00000000000WH000003', '01K5INV00000000000WH000004', 1, TRUE, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000WHSUPPLY05', '01K5INV00000000000WH000001', '01K5INV00000000000WH000005', 3, FALSE, '01JWNY20G23KD4RV5VWYABQYHD', TRUE, NOW(), NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text)
		ON CONFLICT ("id") DO NOTHING;

		-- Locations. Every location_usage value is represented. The physical tree under each
		-- warehouse is: WH root -> zone -> aisle/bin, with complete_path and hierarchy_depth kept
		-- consistent with parent_location_id. The virtual locations (vendor, customer, transit,
		-- scrap, inventory_loss) carry no warehouse_id and are the counterparties every receipt,
		-- delivery, scrap and count adjustment moves against.
