		('01K5INV000000000000LOC0001', 'VIRT/VENDOR', jsonb_build_object('en-US', 'Vendors', 'vi-VN', 'Nhà cung cấp'), 'vendor', NULL, NULL, NULL, 'VIRT/VENDOR', 0, NULL, NULL, NULL, FALSE, TRUE, 'active', jsonb_build_object('en-US', 'Goods originate here on a receipt', 'vi-VN', 'Hàng xuất phát từ đây khi nhập kho'), '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
