		('01K5INV000000000000LOC0003', 'VIRT/TRANSIT', jsonb_build_object('en-US', 'Inter-warehouse Transit', 'vi-VN', 'Hàng đang chuyển kho'), 'transit', NULL, NULL, NULL, 'VIRT/TRANSIT', 0, NULL, NULL, NULL, FALSE, TRUE, 'active', jsonb_build_object('en-US', 'Holds stock that has left one warehouse but not yet arrived at the next', 'vi-VN', 'Giữ hàng đã rời kho nhưng chưa tới kho đích'), '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0004', 'VIRT/SCRAP', jsonb_build_object('en-US', 'Scrapped Goods', 'vi-VN', 'Hàng huỷ'), 'scrap', NULL, NULL, NULL, 'VIRT/SCRAP', 0, NULL, NULL, NULL, FALSE, TRUE, 'active', jsonb_build_object('en-US', 'Destination of every scrap document', 'vi-VN', 'Đích đến của mọi phiếu huỷ hàng'), '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0005', 'VIRT/LOSS', jsonb_build_object('en-US', 'Inventory Adjustment', 'vi-VN', 'Điều chỉnh tồn kho'), 'inventory_loss', NULL, NULL, NULL, 'VIRT/LOSS', 0, NULL, NULL, NULL, FALSE, TRUE, 'active', jsonb_build_object('en-US', 'Counterparty for count adjustments; absorbs both gains and losses', 'vi-VN', 'Đối ứng cho điều chỉnh kiểm kê, nhận cả thừa và thiếu'), '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0006', 'VIRT/PRODUCTION', jsonb_build_object('en-US', 'Virtual Production', 'vi-VN', 'Sản xuất ảo'), 'virtual', NULL, NULL, NULL, 'VIRT/PRODUCTION', 0, NULL, NULL, NULL, FALSE, TRUE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),

		-- WH-CENTRAL: three-step in and out, so it has receiving, quality, stock, picking, packing
