		('01K5INV000000000000LOC0010', 'CEN', jsonb_build_object('en-US', 'Central DC', 'vi-VN', 'Trung tâm phân phối'), 'internal', NULL, '01K5INV00000000000WH000001', NULL, 'CEN', 0, NULL, NULL, NULL, FALSE, TRUE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
