		('01K5INV000000000000LOC0030', 'NOR', jsonb_build_object('en-US', 'North Warehouse', 'vi-VN', 'Kho miền Bắc'), 'internal', NULL, '01K5INV00000000000WH000002', NULL, 'NOR', 0, NULL, NULL, NULL, FALSE, TRUE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
