		('01K5VMKIOSKLOC000000000000', 'KIOSK/001', jsonb_build_object('en-US', 'Kiosk 001', 'vi-VN', 'Kiosk 001'), 'internal', 'storage', NULL, NULL, 'KIOSK/001', 0, NULL, NULL, 'fifo', FALSE, TRUE, 'active', jsonb_build_object('en-US', 'Stock held inside kiosk 001'), '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
